<div class="page-heading"><div><span class="eyebrow"><?= te('CLIENT WORKSPACE') ?></span><h1><?= te('Your project workforce') ?></h1><p class="sub"><?= te('Review deployed teams, approved attendance and issued invoices.') ?></p></div></div>
<?php if($project): ?><section class="card"><h2><?= te('Deployment logistics') ?></h2><div class="grid g4"><?php foreach(['rooms'=>'Rooms reserved','flights'=>'Flights booked','vehicles'=>'Vehicles out','equipment'=>'Equipment outstanding'] as $metric=>$label): ?><div><span class="muted"><?= te($label) ?></span><h2><?= (int)$logistics[$metric] ?></h2></div><?php endforeach; ?></div><?php if($clientEquipment): ?><h3><?= te('Client-owned equipment') ?></h3><div class="scroll"><table><tr><th><?= te('Equipment') ?></th><th><?= te('Asset tag') ?></th><th><?= te('Serial number') ?></th><th><?= te('Employee') ?></th><th><?= te('Returned') ?></th></tr><?php foreach($clientEquipment as $asset): ?><tr><td><?= e($asset['name']) ?></td><td><?= e($asset['asset_tag']) ?></td><td><?= e($asset['serial_number']) ?></td><td><?= e($asset['full_name']) ?></td><td><?= $asset['returned_at']?e(d($asset['returned_at'])):te('Pending') ?></td></tr><?php endforeach; ?></table></div><?php endif; ?></section><?php endif; ?>
<?php if($invoice): ?><section class="card invoice-print"><h2><?= te('Invoice') ?> <?= e($invoice['reference']) ?></h2><p><?= e($project['client_name'].' · '.$project['title']) ?></p><p><?= e(d($invoice['starts_on']).' — '.d($invoice['ends_on'])) ?></p><div class="scroll"><table><thead><tr><th><?= te('Employee') ?></th><th><?= te('Week') ?></th><th><?= te('Hours') ?></th><th><?= te('Client rate') ?></th><th><?= te('Total') ?></th></tr></thead><tbody><?php foreach($invoiceLines as $line): ?><tr><td><?= e($line['worker']) ?></td><td><?= e(d($line['week'])) ?></td><td><?= e($line['hours']) ?></td><td><?= e(money_local($line['rate'])) ?></td><td><?= e(money_local($line['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div><p><strong><?= te('Total') ?> <?= e(money_local($invoice['total'])) ?></strong></p><button type="button" class="btn" onclick="window.print()"><?= te('Print invoice') ?></button></section><?php endif; ?>
<?php if(!$projects): ?><div class="card"><?= te('No authorized projects. Contact your agency administrator.') ?></div><?php else: ?>
<form method="get" class="card row"><label><?= te('Project') ?></label><select name="job_id"><?php foreach($projects as $choice): ?><option value="<?= (int)$choice['id'] ?>" <?= (int)$choice['id']===$jobId?'selected':'' ?>><?= e($choice['title'].' · '.$choice['client_name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Open project') ?></button></form>
