<div class="card scroll"><h2><?= e($project['title'].' · '.$project['site_city'].' · '.$project['site_state']) ?></h2><table><thead><tr><th><?= te('Employee') ?></th><th><?= te('Trade') ?></th><th><?= te('Shift') ?></th><th><?= te('Supervisor') ?></th><th><?= te('Status') ?></th></tr></thead><tbody><?php foreach($crew as $worker): ?><tr><td><?= e($worker['full_name']) ?></td><td><?= e($worker['trade']) ?></td><td><?= e($worker['shift_label']) ?></td><td><?= e($worker['supervisor']) ?></td><td><?= te($worker['status']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="card scroll"><h2><?= te('Approved attendance') ?></h2><form method="get" class="row"><input type="hidden" name="job_id" value="<?= $jobId ?>"><input type="hidden" name="export" value="attendance"><label><?= te('From') ?></label><input type="date" name="from" value="<?= date('Y-m-01') ?>" required><label><?= te('To') ?></label><input type="date" name="to" value="<?= date('Y-m-d') ?>" required><button class="btn ghost sm"><?= te('Export attendance') ?></button></form><p class="muted"><?= te('Client confirmation does not alter payroll approval or wages.') ?></p><table><thead><tr><th><?= te('Date') ?></th><th><?= te('Employee') ?></th><th><?= te('Hours') ?></th><th><?= te('Client review') ?></th></tr></thead><tbody><?php foreach($attendance as $record): ?><tr><td><?= e(d($record['work_date'])) ?></td><td><?= e($record['full_name']) ?></td><td><?= e($record['hours']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="job_id" value="<?= $jobId ?>"><input type="hidden" name="attendance_id" value="<?= (int)$record['id'] ?>"><select name="decision"><option value="confirmed" <?= ($record['decision'] ?? '')==='confirmed'?'selected':'' ?>><?= te('confirmed') ?></option><option value="disputed" <?= ($record['decision'] ?? '')==='disputed'?'selected':'' ?>><?= te('disputed') ?></option></select><input name="note" maxlength="1000" value="<?= e($record['note'] ?? '') ?>" placeholder="<?= te('Review note') ?>"><button class="btn sm"><?= te('Save review') ?></button></form></td></tr><?php endforeach; ?></tbody></table></div>
<div class="card scroll"><h2><?= te('Issued invoices') ?></h2><table><thead><tr><th><?= te('Reference') ?></th><th><?= te('Period') ?></th><th><?= te('Total') ?></th><th><?= te('Status') ?></th></tr></thead><tbody><?php foreach($invoices as $invoice): ?><tr><td><a href="/client-portal?job_id=<?= $jobId ?>&amp;invoice_id=<?= (int)$invoice['id'] ?>"><?= e($invoice['reference']) ?></a></td><td><?= e(d($invoice['starts_on']).' — '.d($invoice['ends_on'])) ?></td><td><?= e(money_local($invoice['total'])) ?></td><td><?= te($invoice['status']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?>

<section class="card"><h2><?= te('Client requests') ?></h2><?php foreach($orders as $request): ?><p><b><?= e($request['title']) ?></b> · <?= te($request['status']) ?> · <?= te($request['source']) ?></p><p><?= e($request['description']) ?></p><?php endforeach; ?></section>

